/* incremental -- incremental active-set rebuild.
 * See incremental.h. Empty unless PYLATKMC_INCREMENTAL is defined. */
#include "incremental.h"

#ifdef PYLATKMC_INCREMENTAL

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "changed_sites.h"
#include "coord_codes.h"
#include "events_base.h"        /* SP_VACANT */
#include "proclist.h"           /* touchup_a */

/* Generated by tools/gen_reach_template.py. Included by the absolute path the
 * build passes: an include search would take a stray copy from this directory. */
#ifndef PT_REACH_TEMPLATE_HEADER
#error "define PT_REACH_TEMPLATE_HEADER as the quoted path of the derived pt_reach_template.h"
#endif
#include PT_REACH_TEMPLATE_HEADER

struct Incremental {
    int32_t   n_sites;

#ifdef PYLATKMC_REPLAY_ORDER
    uint64_t *visit_keys;  /* temporary keys for the selected process */
#endif

    /* Inverse reach, CSR: inv_idx[inv_off[c] .. inv_off[c + 1]) are the
     * anchors whose static reach contains site c. */
    int64_t  *inv_off;      /* [n_sites + 1] */
    int32_t  *inv_idx;

    /* A site is in the set being gathered iff mark[site] == stamp. */
    uint32_t *mark;         /* [n_sites] */
    uint32_t  stamp;
    int32_t  *scratch;      /* [n_sites] the gathered set */

    /* Local active set. act[s] is active_filter_rescan's rule:
     * static || vacant || some vacant site lists s as a 1NN. */
    uint8_t  *is_vac;       /* [n_sites] */
    uint16_t *n_vac_nn1;    /* [n_sites] */
    uint8_t  *act;          /* [n_sites] */

#ifdef PYLATKMC_INCREMENTAL_ORACLE
    AvailSites *full;       /* the oracle's own table */
    uint64_t   *live_pairs, *full_pairs;
    size_t      live_cap, full_cap;
    uint64_t    oracle_checks, oracle_failures;
#endif
};

/* Start gathering a new set. */
static void next_set(Incremental *inc)
{
    if (++inc->stamp == 0) {
        memset(inc->mark, 0, (size_t)inc->n_sites * sizeof *inc->mark);
        inc->stamp = 1;
    }
}

/* Add `site` to the set being gathered; `n` is its size so far. */
static inline int32_t gather(Incremental *inc, int32_t site, int32_t n)
{
    if (inc->mark[site] == inc->stamp) return n;
    inc->mark[site] = inc->stamp;
    inc->scratch[n] = site;
    return n + 1;
}

/* Static reach of anchor `a`, into scratch; returns its size. */
static int32_t reach_of(Incremental *inc, const Lattice *lat, int32_t a)
{
    const int32_t *row = lat->coord_table + (size_t)a * N_NEIGHBOUR_CODES;
    int32_t n = 0;
    next_set(inc);

    n = gather(inc, a, n);
    for (int32_t i = lat->nn1_offsets[a]; i < lat->nn1_offsets[a + 1]; ++i)
        n = gather(inc, lat->nn1_indices[i], n);

    /* An absent neighbour is the stub site n_sites: its species never changes. */
    for (int r = 0; r < PT_N_READ; ++r) {
        int32_t t = row[PT_READ_CODES[r]];
        if (t >= 0 && t < inc->n_sites) n = gather(inc, t, n);
    }
    for (int r = 0; r < PT_N_SHELL; ++r) {
        int32_t m = row[PT_SHELL_CODES[r]];
        if (m < 0 || m >= inc->n_sites) continue;
        for (int32_t i = lat->nn1_offsets[m]; i < lat->nn1_offsets[m + 1]; ++i)
            n = gather(inc, lat->nn1_indices[i], n);
    }
    return n;
}

/* 0 if every 1NN edge s -> t is a real site pair listed both ways. */
static int check_nn1(const Lattice *lat)
{
    for (int32_t s = 0; s < lat->n_sites; ++s) {
        for (int32_t i = lat->nn1_offsets[s]; i < lat->nn1_offsets[s + 1]; ++i) {
            int32_t t = lat->nn1_indices[i];
            int found = 0;
            if (t >= 0 && t < lat->n_sites)
                for (int32_t j = lat->nn1_offsets[t]; j < lat->nn1_offsets[t + 1] && !found; ++j)
                    found = (lat->nn1_indices[j] == s);
            if (!found) {
                fprintf(stderr,
                        "[incremental] 1NN edge %d -> %d is not listed both ways; "
                        "an incremental build needs a symmetric 1NN list\n",
                        (int)s, (int)t);
                return -EINVAL;
            }
        }
    }
    return 0;
}

static int build_inverse_reach(Incremental *inc, const Lattice *lat)
{
    const int32_t n = inc->n_sites;

    /* Count, then fill in ascending anchor order. */
    for (int32_t a = 0; a < n; ++a) {
        int32_t m = reach_of(inc, lat, a);
        for (int32_t i = 0; i < m; ++i) inc->inv_off[inc->scratch[i] + 1]++;
    }
    for (int32_t c = 0; c < n; ++c) inc->inv_off[c + 1] += inc->inv_off[c];

    inc->inv_idx = malloc((size_t)inc->inv_off[n] * sizeof *inc->inv_idx);
    int64_t *next = malloc((size_t)n * sizeof *next);
    if (!inc->inv_idx || !next) {
        free(next);
        return -ENOMEM;
    }
    memcpy(next, inc->inv_off, (size_t)n * sizeof *next);
    for (int32_t a = 0; a < n; ++a) {
        int32_t m = reach_of(inc, lat, a);
        for (int32_t i = 0; i < m; ++i) inc->inv_idx[next[inc->scratch[i]]++] = a;
    }
    free(next);
    return 0;
}

int incremental_create(Incremental **out, const Lattice *lat)
{
    if (!out) return -EINVAL;
    *out = NULL;
    if (!lat || lat->n_sites <= 0 || !lat->coord_table || !lat->nn1_offsets || !lat->nn1_indices)
        return -EINVAL;
    int rc = check_nn1(lat);
    if (rc != 0) return rc;

    Incremental *inc = calloc(1, sizeof *inc);
    if (!inc) return -ENOMEM;
    const size_t n = (size_t)lat->n_sites;
    inc->n_sites = lat->n_sites;
    inc->inv_off = calloc(n + 1, sizeof *inc->inv_off);
    inc->mark    = calloc(n, sizeof *inc->mark);
    inc->scratch = malloc(n * sizeof *inc->scratch);
    inc->is_vac    = calloc(n, sizeof *inc->is_vac);
    inc->n_vac_nn1 = calloc(n, sizeof *inc->n_vac_nn1);
    inc->act       = calloc(n, sizeof *inc->act);
    if (!inc->inv_off || !inc->mark || !inc->scratch
        || !inc->is_vac || !inc->n_vac_nn1 || !inc->act)
        rc = -ENOMEM;
    else
        rc = build_inverse_reach(inc, lat);
    if (rc != 0) {
        incremental_free(inc);
        return rc;
    }
#ifdef PYLATKMC_REPLAY_ORDER
    inc->visit_keys = malloc(n * sizeof *inc->visit_keys);
    if (!inc->visit_keys) {
        incremental_free(inc);
        return -ENOMEM;
    }
#endif
    *out = inc;
    return 0;
}

void incremental_free(Incremental *inc)
{
    if (!inc) return;
#ifdef PYLATKMC_REPLAY_ORDER
    free(inc->visit_keys);
#endif
    free(inc->inv_off);
    free(inc->inv_idx);
    free(inc->mark);
    free(inc->scratch);
    free(inc->is_vac);
    free(inc->n_vac_nn1);
    free(inc->act);
#ifdef PYLATKMC_INCREMENTAL_ORACLE
    avail_sites_free(inc->full);
    free(inc->live_pairs);
    free(inc->full_pairs);
#endif
    free(inc);
}

static inline void set_active(Incremental *inc, const ActiveFilter *af, int32_t s)
{
    inc->act[s] = (uint8_t)(inc->is_vac[s] || inc->n_vac_nn1[s] > 0
                            || active_filter_is_static(af, s));
}

int incremental_start(Incremental **out, const Lattice *lat, const State *st,
                      AvailSites *as, ActiveFilter *af)
{
    if (!out) return -EINVAL;
    *out = NULL;
    if (!st || !st->changed || !as || !af) return -EINVAL;

    Incremental *inc = NULL;
    int rc = incremental_create(&inc, lat);
    if (rc != 0) return rc;

    active_filter_rescan(af, lat, st);
    avail_sites_clear(as);
    const int32_t n_active = active_filter_n_active(af);
    for (int32_t i = 0; i < n_active; ++i)
        touchup_a(lat, st, as, active_filter_site_at(af, i));

    const int32_t n = inc->n_sites;
    for (int32_t s = 0; s < n; ++s) {
        if (st->species[s] != SP_VACANT) continue;
        inc->is_vac[s] = 1;
        for (int32_t i = lat->nn1_offsets[s]; i < lat->nn1_offsets[s + 1]; ++i)
            inc->n_vac_nn1[lat->nn1_indices[i]]++;
    }
    for (int32_t s = 0; s < n; ++s) set_active(inc, af, s);

    *out = inc;
    return 0;
}

void incremental_update(Incremental *inc, const Lattice *lat, const State *st,
                        AvailSites *as, const ActiveFilter *af)
{
    const int32_t *changed = NULL;
    const int32_t n_changed = changed_sites_get(st->changed, &changed);

    /* 1. Local active set. All counts first: changed sites can be 1NN. */
    for (int32_t i = 0; i < n_changed; ++i) {
        const int32_t c = changed[i];
        const uint8_t vac = (st->species[c] == SP_VACANT);
        if (vac == inc->is_vac[c]) continue;
        inc->is_vac[c] = vac;
        for (int32_t j = lat->nn1_offsets[c]; j < lat->nn1_offsets[c + 1]; ++j) {
            if (vac) inc->n_vac_nn1[lat->nn1_indices[j]]++;
            else     inc->n_vac_nn1[lat->nn1_indices[j]]--;
        }
    }
    for (int32_t i = 0; i < n_changed; ++i) {
        const int32_t c = changed[i];
        set_active(inc, af, c);
        for (int32_t j = lat->nn1_offsets[c]; j < lat->nn1_offsets[c + 1]; ++j)
            set_active(inc, af, lat->nn1_indices[j]);
    }

    /* 2. K = union of the inverse reach over the changed sites. */
    int32_t n_k = 0;
    next_set(inc);
    for (int32_t i = 0; i < n_changed; ++i) {
        const int32_t c = changed[i];
        for (int64_t j = inc->inv_off[c]; j < inc->inv_off[c + 1]; ++j)
            n_k = gather(inc, inc->inv_idx[j], n_k);
    }

    /* 3. Delete before re-matching, so that nothing stale survives. */
    for (int32_t i = 0; i < n_k; ++i) avail_sites_del_site(as, inc->scratch[i]);

    /* 4. Re-match the active anchors. */
    for (int32_t i = 0; i < n_k; ++i) {
        const int32_t a = inc->scratch[i];
        if (inc->act[a]) touchup_a(lat, st, as, a);
    }
}

#ifdef PYLATKMC_REPLAY_ORDER
/* active_filter_rescan first visits static sites in ascending site order.
 * It then visits each vac_list entry, followed by that vacancy's CSR row.
 * The first visit wins. Compute that position only for sites enrolled in
 * the selected process. A swap-last vacancy move is reflected immediately
 * because vac_idx_of always gives the current list position. */
static uint64_t first_visit(const Lattice *lat, const State *st,
                            const ActiveFilter *af, int32_t site)
{
    if (active_filter_is_static(af, site)) return (uint32_t)site;

    int32_t first = st->vac_idx_of[site];
    int32_t vacancy = site;
    for (int32_t i = lat->nn1_offsets[site]; i < lat->nn1_offsets[site + 1]; ++i) {
        int32_t neighbor = lat->nn1_indices[i];
        int32_t index = st->vac_idx_of[neighbor];
        if (index >= 0 && (first < 0 || index < first)) {
            first = index;
            vacancy = neighbor;
        }
    }
    if (first < 0) return UINT64_MAX;
    uint64_t key = ((uint64_t)(first + 1) << 32);
    if (vacancy == site) return key;
    /* incremental_create verified every 1NN edge has a reverse edge.
     * Use the first forward occurrence, including when PBC aliases edges. */
    for (int32_t i = lat->nn1_offsets[vacancy]; i < lat->nn1_offsets[vacancy + 1]; ++i)
        if (lat->nn1_indices[i] == site) return key | (uint32_t)(i + 1);
    return UINT64_MAX;
}

static int compare_visit(const void *left, const void *right)
{
    uint64_t a = *(const uint64_t *)left, b = *(const uint64_t *)right;
    return (a > b) - (a < b);
}

int incremental_replay_site(Incremental *inc, const Lattice *lat, const State *st,
                            const ActiveFilter *af, const AvailSites *as,
                            int32_t proc, int32_t *site)
{
    int32_t count = avail_sites_count(as, proc);
    if (count == 1) return 0;
    int32_t slot = avail_sites_slot_of(as, proc, *site);
    if (slot < 0 || slot >= count) return -EILSEQ;
    for (int32_t i = 0; i < count; ++i) {
        int32_t s = avail_sites_site_at(as, proc, i);
        inc->visit_keys[i] = first_visit(lat, st, af, s);
        if (inc->visit_keys[i] == UINT64_MAX) return -EILSEQ;
    }
    qsort(inc->visit_keys, (size_t)count, sizeof *inc->visit_keys, compare_visit);
    uint64_t key = inc->visit_keys[slot];
    uint32_t pass = (uint32_t)(key >> 32), position = (uint32_t)key;
    if (!pass) *site = (int32_t)position;
    else if (!position) *site = st->vac_list[pass - 1];
    else *site = lat->nn1_indices[position - 1];
    return 0;
}
#endif

int32_t incremental_inverse_reach(const Incremental *inc, int32_t site, const int32_t **out)
{
    if (!inc || !out || site < 0 || site >= inc->n_sites) return 0;
    *out = inc->inv_idx + inc->inv_off[site];
    return (int32_t)(inc->inv_off[site + 1] - inc->inv_off[site]);
}

#ifdef PYLATKMC_INCREMENTAL_ORACLE

static int cmp_pair(const void *x, const void *y)
{
    const uint64_t a = *(const uint64_t *)x, b = *(const uint64_t *)y;
    return (a > b) - (a < b);
}

/* Every enrolled (process, site) of `as` as process << 32 | site, sorted. */
static int sorted_pairs(const AvailSites *as, uint64_t **buf, size_t *cap, size_t *n_out)
{
    const int32_t n_procs = avail_sites_n_procs(as);
    size_t n = 0;
    for (int32_t p = 0; p < n_procs; ++p) n += (size_t)avail_sites_count(as, p);
    if (n + 1 > *cap) {     /* + 1: never a zero-length buffer */
        uint64_t *grown = realloc(*buf, (n + 4096) * sizeof *grown);
        if (!grown) return -ENOMEM;
        *buf = grown;
        *cap = n + 4096;
    }
    size_t m = 0;
    for (int32_t p = 0; p < n_procs; ++p) {
        const int32_t count = avail_sites_count(as, p);
        for (int32_t k = 0; k < count; ++k)
            (*buf)[m++] = ((uint64_t)(uint32_t)p << 32)
                        | (uint32_t)avail_sites_site_at(as, p, k);
    }
    qsort(*buf, m, sizeof **buf, cmp_pair);
    *n_out = m;
    return 0;
}

static void print_first_pair(const char *which, size_t count, uint64_t pair)
{
    if (count)
        fprintf(stderr, "[oracle]   first %s pair: process %d at site %d\n",
                which, (int)(pair >> 32), (int)(uint32_t)pair);
}

int incremental_oracle(Incremental *inc, const Lattice *lat, const State *st,
                       const AvailSites *as, ActiveFilter *af)
{
    const int32_t n_sites = inc->n_sites;
    const int32_t n_procs = avail_sites_n_procs(as);
    int rc;

    if (!inc->full) {
        rc = avail_sites_alloc(&inc->full, n_procs, n_sites);
        if (rc != 0) {
            fprintf(stderr, "[oracle] cannot allocate the second table (%d x %d): %d\n",
                    (int)n_procs, (int)n_sites, rc);
            return rc;
        }
        for (int32_t p = 0; p < n_procs; ++p)
            avail_sites_set_rate(inc->full, p, avail_sites_rate(as, p));
    }

    /* The full rebuild, in its own table. The step reads only the static mask
     * of `af`, so rescanning it here cannot change the trajectory. */
    active_filter_rescan(af, lat, st);
    avail_sites_clear(inc->full);
    const int32_t n_active = active_filter_n_active(af);
    for (int32_t i = 0; i < n_active; ++i)
        touchup_a(lat, st, inc->full, active_filter_site_at(af, i));
    avail_sites_refresh_cum_rates(inc->full);

    size_t n_live = 0, n_full = 0;
    rc = sorted_pairs(as, &inc->live_pairs, &inc->live_cap, &n_live);
    if (rc == 0) rc = sorted_pairs(inc->full, &inc->full_pairs, &inc->full_cap, &n_full);
    if (rc != 0) {
        fprintf(stderr, "[oracle] cannot allocate the pair lists: %d\n", rc);
        return rc;
    }

    /* Merge the sorted lists: missing = only in full, extra = only in live. */
    const uint64_t *live = inc->live_pairs, *full = inc->full_pairs;
    size_t n_missing = 0, n_extra = 0;
    uint64_t first_missing = 0, first_extra = 0;
    for (size_t i = 0, j = 0; i < n_live || j < n_full;) {
        if (j == n_full || (i < n_live && live[i] < full[j])) {
            if (!n_extra++) first_extra = live[i];
            ++i;
        } else if (i == n_live || full[j] < live[i]) {
            if (!n_missing++) first_missing = full[j];
            ++j;
        } else {
            ++i;
            ++j;
        }
    }

    int32_t n_active_diff = 0, first_active_diff = -1;
    for (int32_t s = 0; s < n_sites; ++s)
        if ((inc->act[s] != 0) != (active_filter_is_active(af, s) != 0) && !n_active_diff++)
            first_active_diff = s;

    /* Equal counts give bitwise equal prefix sums, so no tolerance. */
    const double r_live = avail_sites_r_tot(as);
    const double r_full = avail_sites_r_tot(inc->full);

    inc->oracle_checks++;
    if (!n_missing && !n_extra && !n_active_diff && r_live == r_full) return 0;

    inc->oracle_failures++;
    fprintf(stderr,
            "[oracle] step %llu: the incremental state is not a full rebuild's: "
            "%zu missing, %zu extra pairs; %d active-set differences; "
            "r_tot %.17g, full rebuild %.17g\n",
            (unsigned long long)st->step, n_missing, n_extra, (int)n_active_diff,
            r_live, r_full);
    print_first_pair("missing", n_missing, first_missing);
    print_first_pair("extra", n_extra, first_extra);
    if (n_active_diff)
        fprintf(stderr, "[oracle]   first active-set difference at site %d\n",
                (int)first_active_diff);
    return -EILSEQ;
}

uint64_t incremental_oracle_checks(const Incremental *inc)
{
    return inc ? inc->oracle_checks : 0;
}

uint64_t incremental_oracle_failures(const Incremental *inc)
{
    return inc ? inc->oracle_failures : 0;
}

#endif /* PYLATKMC_INCREMENTAL_ORACLE */

#endif /* PYLATKMC_INCREMENTAL */
